const item = $input.first();
const root = item.json || {};

// Try multiple common locations where n8n may place the request body
const j =
  root.body ??
  root.data ??
  root.payload ??
  root.query ??
  root.params ??
  root;

// If the body is a STRING (raw JSON), parse it
let body = j;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) {}
}

// Helpers
const pick = (...keys) => {
  for (const k of keys) {
    if (body && body[k] != null && body[k] !== '') return body[k];
  }
  return undefined;
};

const base64 = pick('base64', 'fileBase64', 'imageBase64', 'receiptBase64');
const mimeType = pick('mimeType', 'mime_type', 'contentType', 'content_type');
const fileName = pick('fileName', 'filename', 'name') || 'receipt';

// If JSON has base64 + mimeType
if (base64 && mimeType) {
  return [{
    json: {
      ...body,
      fileName,
      mimeType,
      base64,
      image_url: `data:${mimeType};base64,${base64}`,
    }
  }];
}

// Otherwise, try binary
const bin = item.binary || {};
const binKey = Object.keys(bin)[0];

if (binKey) {
  const f = bin[binKey];
  const b64 = f.data;
  const mt = f.mimeType || 'application/octet-stream';
  const fn = f.fileName || fileName;

  return [{
    json: {
      ...body,
      fileName: fn,
      mimeType: mt,
      base64: b64,
      image_url: `data:${mt};base64,${b64}`,
    }
  }];
}

// If we still can't find anything, return diagnostic info (NOT an error)
return [{
  json: {
    ok: false,
    message: 'Webhook payload did not include base64/mimeType and no binary file was detected.',
    gotTopLevelKeys: Object.keys(root),
    sample: root,
  }
}];

const raw = $input.first().json;
const content = raw.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('No OpenAI content returned');
}

let extracted;
try {
  extracted = JSON.parse(content);
} catch (e) {
  extracted = { raw_text: content };
}

return [{
  json: {
    ok: true,
    extracted
  }
}];

const item = $input.first();

return [{
  json: {
    gotJsonKeys: Object.keys(item.json || {}),
    jsonPreview: item.json || {},
    gotBinaryKeys: Object.keys(item.binary || {}),
  }
}];

const item = $input.first().json;

if (!item.image_url || typeof item.image_url !== 'string') {
  return [{
    json: {
      ok: false,
      error: "image_url missing before OpenAI",
      gotKeys: Object.keys(item),
      preview: item,
    }
  }];
}

// sanity check
if (!item.image_url.startsWith('data:image/')) {
  return [{
    json: {
      ok: false,
      error: "image_url does not look like a data URL",
      startsWith: item.image_url.slice(0, 30),
    }
  }];
}

return [{
  json: {
    model: "gpt-4.1-mini",
    temperature: 0,
    messages: [
      {
        role: "system",
        content: "You are an expense receipt parser. Extract structured data only. Respond in valid JSON."
      },
      {
        role: "user",
        content: [
          {
            type: "text",
            text: "Extract receipt details: merchant, date, subtotal, tax, tip, total, currency, payment_method, last4, category, and line items (name, qty, price). Return JSON only."
          },
          { type: "image_url", image_url: { url: item.image_url } }
        ]
      }
    ]
  }
}];
